<?php

namespace App\Models;

use App\Enums\FreelancerInvoiceStatus;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Carbon;

/**
 * A freelancer's invoice for approved time in a period: uploaded by them,
 * or generated by Hive under a self-billing agreement.
 *
 * @property int $id
 * @property int $person_id
 * @property Carbon $period_start
 * @property Carbon $period_end
 * @property string $invoice_number
 * @property int $net_minor
 * @property int $vat_minor
 * @property int $gross_minor
 * @property int $expected_minor
 * @property FreelancerInvoiceStatus $status
 * @property bool $is_self_billed
 * @property string|null $file_path
 * @property string|null $original_name
 * @property int|null $approved_by
 * @property Carbon|null $approved_at
 * @property Carbon|null $paid_on
 * @property string|null $notes
 * @property Carbon $created_at
 */
class FreelancerInvoice extends Model
{
    protected $fillable = [
        'person_id', 'period_start', 'period_end', 'invoice_number', 'net_minor', 'vat_minor', 'gross_minor', 'expected_minor', 'status',
        'is_self_billed', 'file_path', 'original_name', 'approved_by', 'approved_at', 'paid_on', 'notes',
    ];

    /**
     * @return array<string, string>
     */
    protected function casts(): array
    {
        return [
            'status' => FreelancerInvoiceStatus::class, 'period_start' => 'date', 'period_end' => 'date', 'net_minor' => 'integer', 'vat_minor' => 'integer',
            'gross_minor' => 'integer', 'expected_minor' => 'integer', 'is_self_billed' => 'boolean', 'approved_at' => 'datetime', 'paid_on' => 'date',
        ];
    }

    public function difference(): int
    {
        return $this->net_minor - $this->expected_minor;
    }
}
